function initThemeToggle(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{document.body.classList.toggle("light-theme");const t=document.body.classList.contains("light-theme");localStorage.setItem("theme",t?"light":"dark"),e.textContent=t?"🌙":"☀️"})}function initMobileNav(){const e=document.getElementById("menu-toggle"),t=document.getElementById("nav-menu");e&&t&&e.addEventListener("click",()=>{const n="true"===e.getAttribute("aria-expanded");e.setAttribute("aria-expanded",!n),t.classList.toggle("active")})}function renderStats(){const e=document.getElementById("stats-grid");e&&"undefined"!=typeof DEEPOR_BEEL_INFO&&(e.innerHTML=DEEPOR_BEEL_INFO.quickStats.map(e=>`\n        <div class="stat-card">\n            <div class="stat-icon">${e.icon}</div>\n            <div class="stat-value">${e.value}</div>\n            <div class="stat-label">${e.label}</div>\n        </div>\n    `).join(""))}function renderEcology(){"undefined"!=typeof ECOLOGY_HYDROLOGY&&(setElText("eco-history",ECOLOGY_HYDROLOGY.history),setElText("eco-ramsar",ECOLOGY_HYDROLOGY.ramsarSite),setElText("eco-elephant",ECOLOGY_HYDROLOGY.elephantCorridor),setElText("eco-birds",ECOLOGY_HYDROLOGY.wetlandBirds),setElText("eco-fisheries",ECOLOGY_HYDROLOGY.fisheries),setElText("eco-biodiversity",ECOLOGY_HYDROLOGY.biodiversity))}function setElText(e,t){const n=document.getElementById(e);n&&(n.textContent=t)}function renderSpecies(){const e=document.getElementById("species-grid");e&&"undefined"!=typeof BIRD_SPECIES&&(e.innerHTML=BIRD_SPECIES.map(e=>`\n        <div class="species-card">\n            <img src="${e.image}" alt="${e.name}" loading="lazy" />\n            <div class="species-content">\n                <div class="species-title">${e.icon} ${e.name}</div>\n                <div class="species-scientific">${e.scientificName}</div>\n                <span class="status-badge">${e.status}</span>\n                <p style="font-size: 0.9rem; margin-top: 0.5rem; line-height: 1.4;">${e.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderHotspots(){const e=document.getElementById("hotspots-grid");e&&"undefined"!=typeof MAP_HOTSPOTS&&(e.innerHTML=MAP_HOTSPOTS.map(e=>`\n        <div class="hotspot-card">\n            <div class="hotspot-content">\n                <h3 style="margin: 0 0 0.5rem; color: #38bdf8;">📍 ${e.title}</h3>\n                <div style="font-size: 0.85rem; color: var(--deepor-muted); margin-bottom: 0.5rem;">${e.type} (${e.lat}°N, ${e.lng}°E)</div>\n                <p style="font-size: 0.9rem; margin: 0; line-height: 1.4;">${e.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderGallery(){const e=document.getElementById("gallery-grid");e&&"undefined"!=typeof GALLERY_IMAGES&&(e.innerHTML=GALLERY_IMAGES.map(e=>`\n        <div class="gallery-card">\n            <img src="${e.url}" alt="${e.caption}" loading="lazy" />\n            <div class="gallery-caption">\n                <strong style="font-size: 0.9rem;">${e.caption}</strong>\n                <span style="font-size: 0.75rem; display: block; color: var(--deepor-muted); margin-top: 0.25rem;">Category: ${e.category}</span>\n            </div>\n        </div>\n    `).join(""))}document.addEventListener("DOMContentLoaded",()=>{initThemeToggle(),initMobileNav(),renderStats(),renderEcology(),renderSpecies(),renderHotspots(),renderGallery()});